class Solution {
  public int calculate(String s) {
    int result = 0, last = 0, num = 0;
    char op = '+';
    for (int i = 0; i <= s.length(); i++) {
      char c = i < s.length() ? s.charAt(i) : '+';
      if (c == ' ') continue;
      if (Character.isDigit(c)) {
        num = num * 10 + (c - '0');
        continue;
      }
      // apply the previous operator; * and / bind to the last term before it is added
      if (op == '+' || op == '-') {
        result += last;
        last = op == '+' ? num : -num;
      } else if (op == '*') last *= num;
      else last /= num;
      op = c;
      num = 0;
    }
    return result + last;
  }
}
